/// Sequence `SequenceFileLoad`.
Future<String> sequenceFileLoad() async {
  final run = ts.SequenceRun();
  final dynamic explanationResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ButtonHit': 0,
    'Response': '',
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of Explanation
  final dynamic launchHelpResult = ts.PropObj({
    'Error': ts.PropObj({'Code': 0, 'Msg': '', 'Occurred': false}),
    'Status': '',
    'ExitCode': 0,
    'ReportText': '',
    'Common': ts.PropObj(),
  }); // result of LaunchHelp

  // popup title: "About This Example"
  // popup message: "This example demonstrates how to configure different TMU measurements using the Semiconductor Test Library. | It showcases six different TMU measurement types on digital pins: | 1. MeasurePeriod: |     Measures the period of a digital signal using rising edge detection and publishes the averaged result using the \"Period\" Published Data Id. | 2. MeasurePulseWidth: |     Measures the high pulse width of a digital signal, from the rising edge to the subsequent falling edge at Voh, and publishes the averaged result using the \"PulseWidth\" Published Data Id. | 3. MeasureDutyCycle: |     Measures the duration the signal spends in the high state and publishes it using the \"DutyCycleTime\" Published Data Id, then performs a period measurement to convert that duration into a ratio, which is published using the \"DutyCycleRatio\" Published Data Id. | 4. MeasureRiseTime: |     Measures the rise time of a digital signal, from the low voltage threshold (Vol) to the high voltage threshold (Voh), and publishes the averaged result using the \"RiseTime\" Published Data Id. | 5. MeasureFallTime: |     Measures the fall time of a digital signal, from the high voltage threshold (Voh) to the low voltage threshold (Vol), and publishes the averaged result using the \"FallTime\" Published Data Id. | 6. MeasureSkew: |     Measures the skew between the same edge type occurring on a reference pin (\"C0\") and a target pin (\"C1\"), and publishes the averaged result using the \"Skew\" Published Data Id. | Prerequisites: | 1. Software Requirements: |    - STS Software 26.5.0 or later | 2. Hardware Requirements: |    - An NI Digital Pattern Instrument (PXIe-657x) named \"HSD_6571_C1_S03\" (or update the pin map to use the name of the NI Digital Pattern Instrument in your system, as defined in NI MAX) |    - A signal source driving the measured pins \"C0\" and \"C1\" | Note: | - You do not need the required instruments physically installed in your system to run the example, as it can be run with simulated instruments using Offline Mode. |    However, the TMU measures the timing characteristics of a real signal present on the pin under test. |    Therefore, to obtain actual measurement results from the test steps, you must have the required hardware installed and drive a continuously toggling digital signal onto the measured pins,  |    with the pin levels (Vol/Voh) matching the amplitude of the incoming signal, since edge detection depends on these thresholds. | - Not all digital pattern instruments support the TMU. Refer to the NI Digital Pattern Instruments (PXIe-657x) documentation for details. | Click the Help button below to review the README file accompanying the sequence file for information on how to use this example."
  // popup buttons: "Help" | "OK"
  // Explanation [MessagePopup]: acts through ts.stepHost
  final popup = await ts.stepHost.messagePopup(
    title: 'About This Example',
    message:
        'This example demonstrates how to configure different TMU measurements using the Semiconductor Test Library.\n\nIt showcases six different TMU measurement types on digital pins:\n1. MeasurePeriod:\n    Measures the period of a digital signal using rising edge detection and publishes the averaged result using the "Period" Published Data Id.\n2. MeasurePulseWidth:\n    Measures the high pulse width of a digital signal, from the rising edge to the subsequent falling edge at Voh, and publishes the averaged result using the "PulseWidth" Published Data Id.\n3. MeasureDutyCycle:\n    Measures the duration the signal spends in the high state and publishes it using the "DutyCycleTime" Published Data Id, then performs a period measurement to convert that duration into a ratio, which is published using the "DutyCycleRatio" Published Data Id.\n4. MeasureRiseTime:\n    Measures the rise time of a digital signal, from the low voltage threshold (Vol) to the high voltage threshold (Voh), and publishes the averaged result using the "RiseTime" Published Data Id.\n5. MeasureFallTime:\n    Measures the fall time of a digital signal, from the high voltage threshold (Voh) to the low voltage threshold (Vol), and publishes the averaged result using the "FallTime" Published Data Id.\n6. MeasureSkew:\n    Measures the skew between the same edge type occurring on a reference pin ("C0") and a target pin ("C1"), and publishes the averaged result using the "Skew" Published Data Id.\n\nPrerequisites:\n1. Software Requirements:\n   - STS Software 26.5.0 or later\n2. Hardware Requirements:\n   - An NI Digital Pattern Instrument (PXIe-657x) named "HSD_6571_C1_S03" (or update the pin map to use the name of the NI Digital Pattern Instrument in your system, as defined in NI MAX)\n   - A signal source driving the measured pins "C0" and "C1"\n\nNote:\n- You do not need the required instruments physically installed in your system to run the example, as it can be run with simulated instruments using Offline Mode.\n   However, the TMU measures the timing characteristics of a real signal present on the pin under test.\n   Therefore, to obtain actual measurement results from the test steps, you must have the required hardware installed and drive a continuously toggling digital signal onto the measured pins, \n   with the pin levels (Vol/Voh) matching the amplitude of the incoming signal, since edge detection depends on these thresholds.\n- Not all digital pattern instruments support the TMU. Refer to the NI Digital Pattern Instruments (PXIe-657x) documentation for details.\n\nClick the Help button below to review the README file accompanying the sequence file for information on how to use this example.',
    buttons: ['Help', 'OK', '', '', '', ''],
  );
  explanationResult.ButtonHit = popup.buttonHit;
  explanationResult.Response = popup.response;
  explanationResult.Status = 'Done';
  run.record(explanationResult.Status);
  // runs executable: notepad "README.md" (WAIT_NONE)
  if (ts.cond('RunState.PreviousStep.Result.ButtonHit==1')) {
    // precondition of LaunchHelp
    // LaunchHelp [CallExecutable]: acts through ts.stepHost
    await ts.stepHost.runStepType(
      'CallExecutable',
      ts.StepPhase.post,
      ts.PropObj({
        'Executable': 'notepad',
        'ExecutableExpr': '',
        'SpecifyExeByExpr': false,
        'ExecutableCalled': '',
        'Arguments': '"README.md"',
        'WaitCondition': 'WAIT_NONE',
        'TimeToWait': 0,
