        'RemoteSettings': ts.PropObj({
          'Enabled': false,
          'Host': '""',
          'HostByExpr': true,
          'Port': '13540',
          'Password': '',
          'PasswordByExpr': false,
        }),
        'StdInput': ts.PropObj({'Type': 0, 'Source': '""', 'IsExpr': false}),
        'StdOutput': ts.PropObj({'Dest': 0, 'Expr': 'Step.StdOutput.Text', 'IsExpr': false, 'Text': ''}),
        'StdError': ts.PropObj({
          'Dest': 0,
          'Expr': 'Step.StdError.Text',
          'IsExpr': false,
          'Text': '',
          'Action': 0,
          'SetErrorMsg': false,
        }),
      }),
      launchHelpResult,
    );
    launchHelpResult.Status = 'Done';
    run.record(launchHelpResult.Status);
  } else {
    launchHelpResult.Status = 'Skipped';
  }

  return run.status;
}
